import sys
from collections import deque


def ladder_brute(begin, end, words):
    if end not in words:
        return 0

    def adj(a, b):
        return sum(x != y for x, y in zip(a, b)) == 1

    q = deque([(begin, 1)])
    seen = {begin}
    word_list = list(words)
    while q:
        w, d = q.popleft()
        if w == end:
            return d
        for nw in word_list:
            if nw not in seen and adj(w, nw):
                seen.add(nw)
                q.append((nw, d + 1))
    return 0


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    begin = data[0]
    end = data[1]
    n = int(data[2])
    words = set(data[3:3 + n])
    print(ladder_brute(begin, end, words))

import sys


def ladder_opt(begin, end, words):
    if end not in words:
        return 0
    L = len(begin)
    fwd, bwd = {begin}, {end}
    fseen, bseen = {begin}, {end}
    step = 1
    while fwd and bwd:
        if len(fwd) > len(bwd):
            fwd, bwd = bwd, fwd
            fseen, bseen = bseen, fseen
        nxt = set()
        for w in fwd:
            for i in range(L):
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    nw = w[:i] + c + w[i + 1:]
                    if nw in bseen:
                        return step + 1
                    if nw in words and nw not in fseen:
                        fseen.add(nw)
                        nxt.add(nw)
        fwd = nxt
        step += 1
    return 0


