import sys
from collections import defaultdict


def ladder_best(begin, end, words):
    if end not in words:
        return 0
    L = len(begin)
    wild = defaultdict(list)
    for w in words:
        for i in range(L):
            wild[w[:i] + '_' + w[i + 1:]].append(w)
    fwd, bwd = {begin}, {end}
    fseen, bseen = {begin}, {end}
    step = 1
    while fwd and bwd:
        if len(fwd) > len(bwd):
            fwd, bwd = bwd, fwd
            fseen, bseen = bseen, fseen
        nxt = set()
        for w in fwd:
            for i in range(L):
                key = w[:i] + '_' + w[i + 1:]
                for nw in wild.get(key, ()):
                    if nw in bseen:
                        return step + 1
                    if nw not in fseen:
                        fseen.add(nw)
                        nxt.add(nw)
        fwd = nxt
        step += 1
    return 0


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    begin = data[0]
    end = data[1]
    n = int(data[2])
    words = set(data[3:3 + n])
    print(ladder_best(begin, end, words))
